<?php
declare(strict_types=1);
$root=dirname(__DIR__);$dsn=(string)getenv('DB_DSN');$dbUser=(string)getenv('DB_USER');$dbPass=(string)getenv('DB_PASS');if($dsn==='')throw new RuntimeException('DB_DSN is required.');
$pdo=new PDO($dsn,$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
foreach(['installer','storage','jobs','concurrency','functions','subscriptions','account-admin','account-membership','shell','access','notifications','rate-limit','ai','ai-access','source-integrity','annotation-intelligence','research-workspace','research-knowledge','research-intelligence','research-reports','conversations','agent-actions','agent-chat','cognitive-feed','research-entities','proactive-intelligence','research-automation','research-agent-workspace','research-agents','research-tasks','research-programs','research-missions','research-accounts','sponsored-research-campaigns','sponsored-research-participation','sponsored-research-submissions','sponsored-research-reviews','data-attribution','sponsored-research-finance','data-datasets','sponsored-research-projects','sponsored-research-project-compensation'] as $lib)require_once $root.'/app/'.$lib.'.php';
function ok11(bool $ok,string $m):void{if(!$ok)throw new RuntimeException('FAIL: '.$m);echo "PASS: $m\n";}
$run='p80s11'.substr(bin2hex(random_bytes(5)),0,10);$pub=fn(string $p)=>$p.'-'.$run.'-'.substr(bin2hex(random_bytes(3)),0,6);
$make=function(string $name,string $role='user')use($pdo,$run,$pub):array{$u=substr(strtolower($name).'_'.$run,0,48);$pdo->prepare("INSERT INTO users(public_id,username,display_name,email,email_verified_at,status,role,plan_tier,live_presence_mode) VALUES(?,?,?,?,NOW(),'active',?,'pro','cloaked')")->execute([$pub('u'),$u,$name,$u.'@example.test',$role]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT IGNORE INTO user_preferences(user_id) VALUES(?)')->execute([$id]);$q=$pdo->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);return $q->fetch();};
$admin=$make('CompAdmin','admin');$sponsor=$make('CompSponsor');$researcher=$make('CompResearcher');
$sampleSettings=sponsored_project_sample_settings($pdo);ok11((int)$sampleSettings['sample_data_enabled']===1,'Sample Sponsored Project data defaults on for Admin demo review.');
$sampleProjects=sponsored_project_sample_projects($pdo);ok11(count($sampleProjects)===3&&array_reduce($sampleProjects,fn($ok,$x)=>$ok&&!empty($x['sample_data']),true),'Admin receives three clearly marked non-operational sample projects.');
sponsored_project_sample_toggle($pdo,$admin,false);ok11(sponsored_project_sample_projects($pdo)===[],'Admin can turn sample project data off.');
sponsored_project_sample_toggle($pdo,$admin,true);ok11(count(sponsored_project_sample_projects($pdo))===3,'Admin can turn sample project data back on.');
$pkg=(int)$pdo->query("SELECT id FROM subscription_packages WHERE slug='basic-user' LIMIT 1")->fetchColumn();
$pdo->prepare("INSERT INTO accounts(public_id,account_type,name,owner_user_id,personal_user_id,package_id,subscription_status,period_start,period_end,status) VALUES(?,'personal',?,?,?,?, 'active',CURRENT_DATE,DATE_ADD(CURRENT_DATE,INTERVAL 1 MONTH),'active')")->execute([$pub('acct'),'Comp Account',(int)$sponsor['id'],(int)$sponsor['id'],$pkg]);$acct=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO account_members(account_id,user_id,account_role) VALUES(?,?,'owner')")->execute([$acct,(int)$sponsor['id']]);$q=$pdo->prepare('SELECT public_id FROM accounts WHERE id=?');$q->execute([$acct]);$acctPublic=(string)$q->fetchColumn();
sponsor_account_apply($pdo,$sponsor,['organization_name'=>'Public Research Sponsor']);research_account_admin_decide($pdo,$admin,(int)$sponsor['id'],'sponsor_account','approved','Approved.','organization');
research_account_apply($pdo,$researcher,['specialties'=>'market research','languages'=>'English']);research_account_admin_decide($pdo,$admin,(int)$researcher['id'],'research_account','approved','Approved.','identity');
$campaign=sponsored_research_campaign_create($pdo,$sponsor,['account_id'=>$acctPublic,'title'=>'Paid Public Project','brief'=>'Research an open market question.','objective'=>'Produce an evidence-backed report.','questions'=>['What does the evidence support?'],'access_mode'=>'public','budget_currency'=>'USD','budget'=>'1000.00','researcher_compensation'=>'250.00','max_participants'=>5,'eligibility'=>['min_verification'=>'identity','specialties'=>['market research']],'disclosures'=>['sponsorship_disclosure_required'=>false,'conflict_disclosure_required'=>false,'nda_required'=>false],'submission_deadline'=>'2030-12-31 23:59:00']);
$campaign=sponsored_research_campaign_set_status($pdo,$sponsor,(string)$campaign['public_id'],'open');sponsored_research_campaign_terms_publish($pdo,$sponsor,(string)$campaign['public_id'],'Complete the project through your assigned Research Agent.','Initial terms.');
$list=sponsored_project_public_list($pdo,'Paid Public',20);ok11(count(array_filter($list,fn($x)=>$x['public_id']===$campaign['public_id']))===1,'Public marketplace lists open priced public Sponsored Projects.');
$public=sponsored_project_public_get($pdo,(string)$campaign['public_id']);ok11($public!==null&&(int)$public['researcher_compensation_cents']===25000&&$public['organization_name']==='Public Research Sponsor','Public project detail exposes sponsor and advertised flat fee.');

$private=sponsored_research_campaign_create($pdo,$sponsor,['account_id'=>$acctPublic,'title'=>'Private Paid Project','brief'=>'Private brief.','objective'=>'Private objective.','questions'=>['Private question?'],'access_mode'=>'private','budget'=>'500.00','researcher_compensation'=>'100.00','submission_deadline'=>'2030-12-31 23:59:00']);$private=sponsored_research_campaign_set_status($pdo,$sponsor,(string)$private['public_id'],'open');
$unpriced=sponsored_research_campaign_create($pdo,$sponsor,['account_id'=>$acctPublic,'title'=>'Unpriced Public Project','brief'=>'Unpriced brief.','objective'=>'Unpriced objective.','questions'=>['Unpriced question?'],'access_mode'=>'public','budget'=>'500.00','researcher_compensation'=>'0','submission_deadline'=>'2030-12-31 23:59:00']);$unpriced=sponsored_research_campaign_set_status($pdo,$sponsor,(string)$unpriced['public_id'],'open');
$all=sponsored_project_public_list($pdo,'',100);$ids=array_column($all,'public_id');ok11(!in_array($private['public_id'],$ids,true)&&!in_array($unpriced['public_id'],$ids,true),'Public marketplace excludes private and unpriced projects.');

$projectPublic=$pub('proj');$convPublic=$pub('conv');$agentPublic=$pub('agent');
$pdo->prepare("INSERT INTO research_projects(public_id,owner_user_id,title,description,status) VALUES(?,?,?,?,'active')")->execute([$projectPublic,(int)$researcher['id'],'Comp Agent Project','Paid Sponsored Project']);$projectId=(int)$pdo->lastInsertId();
$pdo->prepare("INSERT INTO conversations(public_id,conversation_type,created_by_user_id,title) VALUES(?,'agent',?,?)")->execute([$convPublic,(int)$researcher['id'],'Comp Research Agent']);$convId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO conversation_members(conversation_id,user_id,member_role) VALUES(?,?,'owner')")->execute([$convId,(int)$researcher['id']]);
$pdo->prepare("INSERT INTO research_agents(public_id,owner_user_id,project_id,conversation_id,name,visibility,status,monitoring_cadence) VALUES(?,?,?,?,?,'private','active','manual')")->execute([$agentPublic,(int)$researcher['id'],$projectId,$convId,'Comp Research Agent']);
$assignment=sponsored_project_assign_agent($pdo,$researcher,(string)$campaign['public_id'],$agentPublic,['accept_terms'=>true]);
$comp=sponsored_project_compensation_for_assignment($pdo,(int)$assignment['id']);ok11($comp!==null&&(int)$comp['amount_cents']===25000&&$comp['status']==='pending','Assignment freezes the advertised flat fee as pending compensation.');

$campaign=sponsored_research_campaign_update($pdo,$sponsor,(string)$campaign['public_id'],['researcher_compensation'=>'350.00','reason'=>'Increase fee for future researchers.']);
sponsored_research_campaign_terms_publish($pdo,$sponsor,(string)$campaign['public_id'],'Updated project terms after compensation revision.','Republish current terms.');
sponsored_project_assign_agent($pdo,$researcher,(string)$campaign['public_id'],$agentPublic,['accept_terms'=>true]);
$compAgain=sponsored_project_compensation_for_assignment($pdo,(int)$assignment['id']);ok11((int)$compAgain['amount_cents']===25000,'Existing researcher keeps the original frozen fee after the advertised fee changes.');
$current=sponsored_research_campaign_by_public($pdo,(string)$campaign['public_id']);ok11((int)$current['researcher_compensation_cents']===35000,'Updated project advertises the new fee for future researchers.');

$project=project_access($pdo,(int)$researcher['id'],$projectPublic);$doc=research_agent_workspace_create_document($pdo,$researcher,$project,['title'=>'Paid Deliverable','body'=>'Evidence-backed paid research.','summary'=>'Paid sponsored document.'],true);
$submission=sponsored_project_submit($pdo,$researcher,(string)$campaign['public_id'],[['type'=>'document','public_id'=>(string)$doc['public_id']]],'Paid Submission','Deliverable.',true);
$accepted=sponsored_project_admin_status($pdo,$admin,(string)$submission['public_id'],'accepted','Accepted for completion.');
$earned=sponsored_project_compensation_for_assignment($pdo,(int)$assignment['id']);ok11($earned['status']==='earned'&&(int)$earned['accepted_submission_id']===(int)$accepted['id']&&!empty($earned['earned_at']),'Accepted submission atomically earns the exact frozen compensation.');

$approved=sponsored_project_compensation_admin_transition($pdo,$admin,(string)$earned['public_id'],'approved_for_payment','','Finance approved.');
ok11($approved['status']==='approved_for_payment'&&!empty($approved['approved_at']),'Admin can approve earned compensation for payment.');
$missingRef=false;try{sponsored_project_compensation_admin_transition($pdo,$admin,(string)$earned['public_id'],'paid','','');}catch(InvalidArgumentException $e){$missingRef=true;}ok11($missingRef,'Paid transition requires a payment reference.');
$paid=sponsored_project_compensation_admin_transition($pdo,$admin,(string)$earned['public_id'],'paid','manual-pay-'.$run,'Paid outside Annotated.');
ok11($paid['status']==='paid'&&!empty($paid['paid_at'])&&$paid['payment_reference']==='manual-pay-'.$run,'Admin records paid compensation independently from research acceptance.');
$reopen=false;try{sponsored_project_assign_agent($pdo,$researcher,(string)$campaign['public_id'],$agentPublic,['accept_terms'=>true]);}catch(RuntimeException $e){$reopen=str_contains($e->getMessage(),'completed');}ok11($reopen,'Completed Sponsored Project assignment cannot be silently reopened after acceptance/payment.');

$voidCampaign=sponsored_research_campaign_create($pdo,$sponsor,['account_id'=>$acctPublic,'title'=>'Void Pending Project','brief'=>'Project used to verify pending compensation void.','objective'=>'Verify terminal cancellation.','questions'=>['Should pending compensation stop work?'],'access_mode'=>'public','budget'=>'200.00','researcher_compensation'=>'50.00','eligibility'=>['min_verification'=>'identity'],'disclosures'=>['sponsorship_disclosure_required'=>false,'conflict_disclosure_required'=>false,'nda_required'=>false],'submission_deadline'=>'2030-12-31 23:59:00']);
$voidCampaign=sponsored_research_campaign_set_status($pdo,$sponsor,(string)$voidCampaign['public_id'],'open');sponsored_research_campaign_terms_publish($pdo,$sponsor,(string)$voidCampaign['public_id'],'Void test terms.','Initial terms.');
$voidAssignment=sponsored_project_assign_agent($pdo,$researcher,(string)$voidCampaign['public_id'],$agentPublic,['accept_terms'=>true]);$voidComp=sponsored_project_compensation_for_assignment($pdo,(int)$voidAssignment['id']);
$voidReason=false;try{sponsored_project_compensation_admin_transition($pdo,$admin,(string)$voidComp['public_id'],'voided','','');}catch(InvalidArgumentException $e){$voidReason=true;}ok11($voidReason,'Voiding compensation requires an Admin reason.');
$voided=sponsored_project_compensation_admin_transition($pdo,$admin,(string)$voidComp['public_id'],'voided','','Sponsor cancelled project before work was accepted.');
$q=$pdo->prepare('SELECT status,agent_submit_enabled,removed_at FROM sponsored_research_agent_assignments WHERE id=?');$q->execute([(int)$voidAssignment['id']]);$removed=$q->fetch();ok11($voided['status']==='voided'&&$removed['status']==='removed'&&(int)$removed['agent_submit_enabled']===0&&!empty($removed['removed_at']),'Voiding pending compensation atomically removes the active assignment and disables submission.');

$userComp=sponsored_project_compensations_for_researcher($pdo,(int)$researcher['id'],20);$paidRows=array_values(array_filter($userComp,fn($row)=>(string)$row['public_id']===(string)$paid['public_id']&&(string)$row['status']==='paid'));ok11(count($paidRows)===1,'Researcher compensation view returns the paid project state alongside other compensation records.');
$q=$pdo->prepare("SELECT notification_type FROM notifications WHERE user_id=? AND notification_type LIKE 'research_sponsored_compensation_%' ORDER BY id");$q->execute([(int)$researcher['id']]);$types=$q->fetchAll(PDO::FETCH_COLUMN);ok11(in_array('research_sponsored_compensation_earned',$types,true)&&in_array('research_sponsored_compensation_approved_for_payment',$types,true)&&in_array('research_sponsored_compensation_paid',$types,true),'Researcher receives earned, approved, and paid notifications.');
$q=$pdo->prepare("SELECT event_type FROM sponsored_research_agent_events WHERE assignment_id=? ORDER BY id");$q->execute([(int)$assignment['id']]);$events=$q->fetchAll(PDO::FETCH_COLUMN);foreach(['project_compensation_agreed','project_compensation_earned','project_compensation_approved_for_payment','project_compensation_paid'] as $event)ok11(in_array($event,$events,true),'Audit ledger records '.$event.'.');
echo "Phase 80 Section 11 project compensation/public marketplace database journey passed.\n";
